3. Implementation of an in-memory key-value cache where each element has a TTL (time to live), and once the TTL expires, the element is automatically evicted. I provided a Java implementation for the same.

import java.util.*;

// Represents a cache item with a creation timestamp, TTL (time-to-live), and a key class Item { long timestamp; // The time when the item was inserted int ttl; // Time-to-live in seconds String key; // The key associated with this item

Item(String key, int ttl) { this.timestamp = java.time.Instant.now().getEpochSecond(); // Set current time as creation time this.key = key; this.ttl = ttl; } }

public class Main {

// Map to store key-value pairs HashMap<String, Object> hmap = new HashMap<>();

// Min-heap to track items based on TTL (soonest to expire first) PriorityQueue<Item> pq = new PriorityQueue<>((a, b) -> a.ttl - b.ttl);

public static void main(String[] args) { Main mainObj = new Main();

// Background thread to continuously check and remove expired entries Thread t = new Thread(() -> { while (true) { mainObj.cooldown(200); // Sleep for 200 milliseconds between checks

synchronized (mainObj) { // Synchronize to avoid concurrent modification issues Item curr = mainObj.pq.peek(); // Peek at the earliest-expiring item

while (curr != null && mainObj.getSeconds() - curr.timestamp >= curr.ttl) { // If the item has expired, remove it from both map and queue mainObj.pq.poll(); mainObj.hmap.remove(curr.key); System.out.println("removed key :" + curr.key); curr = mainObj.pq.peek(); // Check the next item } } } });

t.start(); // Start the cleanup thread

// Insert two items with different TTLs mainObj.insert("1", "hello", 3); // expires after 3 seconds mainObj.insert("2", "world", 5); // expires after 5 seconds }

// Inserts a key-value pair with TTL into the cache public synchronized void insert(String key, Object o, int ttl) { hmap.put(key, o); pq.add(new Item(key, ttl)); }

// Pauses the thread for the given duration public void cooldown(int milis) { try { Thread.sleep(milis); } catch (Exception e) { // ignore } }

// Returns current time in seconds since epoch private long getSeconds() { return java.time.Instant.now().getEpochSecond(); } }

